// one reading per hour for the last 7 days, following a day/night cycle

const HOURS_IN_WEEK = 7 * 24;

// a repeatable wobble between -1 and 1, so the lines look natural
// but stay the same on every refresh (Math.random would change them each time)
function wobble(i, seed) {
    return Math.sin(i * 1.7 + seed) * Math.sin(i * 0.31 + seed * 2);
}

// dew point worked out from temperature and humidity (Magnus formula),
// the usual way to get it from a temperature/humidity sensor
function dewPoint(temperature, humidity) {
    const gamma = Math.log(humidity / 100) + (17.62 * temperature) / (243.12 + temperature);
    return (243.12 * gamma) / (17.62 - gamma);
}

// rounds to 1 decimal place, e.g. 19.4378 -> 19.4
function round1(n) {
    return Math.round(n * 10) / 10;
}

// start of the current hour, e.g. 14:37 -> 14:00
const now = new Date();
now.setMinutes(0, 0, 0);

export const weekOfReadings = Array.from({ length: HOURS_IN_WEEK + 1 }, (_, i) => {
    // oldest reading first, newest (this hour) last
    const time = new Date(now.getTime() - (HOURS_IN_WEEK - i) * 60 * 60 * 1000);

    // -1 around 03:00 (coolest) up to 1 around 15:00 (warmest)
    const daily = Math.sin(((time.getHours() - 9) / 24) * 2 * Math.PI);

    const temperature = 16 + 8 * daily + 3 * Math.sin(i / 40) + 1.5 * wobble(i, 1);
    const humidity = Math.min(100, Math.max(30, 74 - 24 * daily + 6 * wobble(i, 2)));
    const wind = Math.max(0, 3 + 2 * daily + 1.5 * wobble(i, 3));

    return {
        time,
        temperature: round1(temperature),
        dewPoint: round1(dewPoint(temperature, humidity)),
        humidity: Math.round(humidity),
        wind: round1(wind),
    };
});